const incoming = $json;
const body = incoming.body ?? incoming;
const headers = incoming.headers ?? {};
const expectedToken = $env.N8N_AUDIT_WEBHOOK_TOKEN || '';
const receivedToken = headers['x-step-internal-token'] || headers['X-STEP-INTERNAL-TOKEN'] || '';
if (expectedToken && receivedToken !== expectedToken) throw new Error('Token interno do webhook inválido');
if (!body.opportunity?.opportunity_id) throw new Error('opportunity.opportunity_id é obrigatório');
if (!body.package?.entries?.length) throw new Error('O pacote não contém documentos extraídos');

function clean(value) { return String(value ?? '').replace(/\u0000/g, '').trim(); }
function entryText(entry) {
  const extracted = entry.extracted || {};
  const content = extracted.content || [];
  const blocks = [];
  if (extracted.kind === 'pdf') {
    for (const page of content) blocks.push(`[Página ${page.page}] ${clean(page.text)}`);
  } else if (extracted.kind === 'document') {
    for (const part of content) {
      if (part.paragraphs?.length) blocks.push(part.paragraphs.map(clean).filter(Boolean).join('\n'));
      for (const table of part.tables || []) blocks.push(table.map(row => row.map(clean).join(' | ')).join('\n'));
    }
  } else if (extracted.kind === 'spreadsheet') {
    for (const sheet of content) blocks.push(`[Planilha ${clean(sheet.sheet || 'Dados')}]\n${(sheet.rows || []).map(row => row.map(clean).join(' | ')).join('\n')}`);
  } else if (extracted.kind === 'email') {
    for (const mail of content) blocks.push(`Assunto: ${clean(mail.subject)}\nDe: ${clean(mail.from)}\nPara: ${clean(mail.to)}\nData: ${clean(mail.date)}\n${clean(mail.body)}`);
  } else {
    for (const part of content) blocks.push(clean(part.text || JSON.stringify(part)));
  }
  return blocks.join('\n\n').slice(0, 18000);
}

const clientDocs = [];
const stepDocs = [];
const unknownDocs = [];
let totalChars = 0;
for (const entry of body.package.entries) {
  if (entry.extraction_status !== 'extracted') continue;
  let text = entryText(entry);
  if (!text) continue;
  const remaining = 150000 - totalChars;
  if (remaining <= 0) break;
  text = text.slice(0, remaining);
  totalChars += text.length;
  const doc = { path: entry.path, type: entry.document_type, group: entry.group, text };
  if (entry.source_owner === 'client') clientDocs.push(doc);
  else if (entry.source_owner === 'step') stepDocs.push(doc);
  else unknownDocs.push(doc);
}
if (!clientDocs.length) throw new Error('Nenhum documento do cliente foi identificado');
if (!stepDocs.length) throw new Error('Nenhum documento STEP foi identificado');

function render(docs) {
  return docs.map(doc => `\n===== ${doc.path} | ${doc.type} =====\n${doc.text}`).join('\n');
}
const systemPrompt = `Você é um auditor adversarial sênior da STEP Oil & Gas para propostas industriais. Use somente as evidências fornecidas. Nunca invente requisitos, preços, prazos, normas ou compromissos. Cada item deve citar o caminho exato do documento e página, planilha, seção ou linha quando disponível. Quando não houver cobertura suficiente, use not_verifiable. Responda exclusivamente JSON válido, sem markdown.`;
const extractionPrompt = `OPORTUNIDADE\n${JSON.stringify(body.opportunity)}\n\nDOCUMENTOS DO CLIENTE\n${render(clientDocs)}\n\nDOCUMENTOS STEP\n${render(stepDocs)}\n\nDOCUMENTOS NÃO CLASSIFICADOS\n${render(unknownDocs)}\n\nExtraia e normalize:\n1. Todos os requisitos do cliente: técnicos, comerciais, contratuais, qualidade, documentação, prazo, quantidade, materiais, testes, normas e condições de pagamento.\n2. Todos os compromissos da STEP: escopo, materiais, prazo, preço, impostos, garantias, exclusões, premissas e desvios.\n3. Itens não verificáveis.\n\nRetorne exatamente este formato:\n{\n  "requirements": [{"id":"REQ-001","category":"technical|commercial|contractual|quality|schedule|documentation|other","requirement":"...","mandatory":true,"source_document":"caminho exato","source_location":"página/planilha/seção","source_evidence":"trecho resumido","status":"not_verifiable"}],\n  "commitments": [{"id":"COM-001","category":"...","commitment":"...","source_document":"caminho exato","source_location":"...","source_evidence":"..."}],\n  "not_verifiable": [{"topic":"...","reason":"...","source_document":"..."}],\n  "document_summary": [{"source_document":"...","role":"client|step|unknown","summary":"..."}]\n}`;
return [{json:{opportunity: body.opportunity, package: body.package, clientDocs, stepDocs, unknownDocs, systemPrompt, extractionPrompt}}];

function parseJson(value) {
  const text = String(value || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'); const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(text.slice(start, end + 1));
  throw new Error('O modelo não retornou JSON válido na extração');
}
const content = $json.message?.content ?? $json.choices?.[0]?.message?.content ?? $json.response ?? '';
const extraction = parseJson(content);
const base = $('Preparar Dossiê').first().json;
const auditPrompt = `OPORTUNIDADE
${JSON.stringify(base.opportunity)}

REQUISITOS E COMPROMISSOS EXTRAÍDOS
${JSON.stringify(extraction)}

Analise requisito por requisito contra os compromissos STEP. Identifique inconsistências técnicas, comerciais, contratuais, de quantidade, material, prazo, norma, documentação e preço. Não altere preço, prazo ou obrigação sem evidência; quando uma correção depender de decisão humana, marque requires_human_validation=true. Crie também uma proposta revisada completa, pronta para revisão humana, incorporando apenas correções suportadas.

Retorne exatamente JSON válido:
{
 "summary":{"recommendation":"submit|submit_with_reservations|review_before_submit|do_not_submit","risk_level":"critical|high|medium|low","executive_opinion":"...","coverage_percent":0,"adherence_percent":0},
 "findings":[{"id":"F-001","severity":"critical|high|medium|low|informational","category":"technical|commercial|contractual|quality|schedule|documentation|scope","title":"...","inconsistency":"...","impact":"...","client_evidence":"documento + localização + resumo","step_evidence":"documento + localização + resumo ou not_verifiable","required_correction":"...","blocking":true}],
 "corrections":[{"id":"C-001","section":"seção da proposta","current_text":"texto/condição atual ou not_verifiable","corrected_text":"texto recomendado","reason":"...","finding_ids":["F-001"],"requires_human_validation":false}],
 "corrected_proposal":{"title":"Proposta Técnico-Comercial Revisada","introduction":"...","sections":[{"title":"Escopo de fornecimento","paragraphs":["..."],"bullets":["..."]}],"exclusions":["..."]},
 "assumptions":["..."],
 "not_verifiable":${JSON.stringify(extraction.not_verifiable || [])}
}`;
return [{json:{...base, extraction, auditPrompt}}];

function parseJson(value) {
  const text = String(value || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'); const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(text.slice(start, end + 1));
  throw new Error('O modelo não retornou JSON válido na auditoria final');
}
const content = $json.message?.content ?? $json.choices?.[0]?.message?.content ?? $json.response ?? '';
const finalAnalysis = parseJson(content);
const base = $('Interpretar Extração').first().json;
finalAnalysis.requirements = base.extraction.requirements || [];
finalAnalysis.commitments = base.extraction.commitments || [];
finalAnalysis.not_verifiable = finalAnalysis.not_verifiable || base.extraction.not_verifiable || [];
finalAnalysis.model = $env.LLM_MODEL || '';
return [{json:{opportunity:base.opportunity, package:base.package, analysis:finalAnalysis}}];
